export type CompositionLayerKind='composition'|'shape'|'text'|'footage'|'adjustment';
export interface CompositionLayer {readonly id:string;readonly name:string;readonly parentId:string|null;readonly kind:CompositionLayerKind;readonly compositionId:string|null;readonly visible:boolean;readonly locked:boolean;readonly opacity:number}
export interface CompositionTreeRow {readonly layer:CompositionLayer;readonly depth:number;readonly hasChildren:boolean}
export function validateCompositionLayers(layers:readonly CompositionLayer[],compositionId:string):void {
 if(!compositionId.trim()||compositionId.length>256||layers.length>50000)throw new RangeError('Invalid composition identity or layer budget');const map=new Map<string,CompositionLayer>();
 for(const layer of layers){if(!layer.id.trim()||layer.id.length>256||!layer.name.trim()||layer.name.length>512||map.has(layer.id)||!['composition','shape','text','footage','adjustment'].includes(layer.kind)||typeof layer.visible!=='boolean'||typeof layer.locked!=='boolean'||!Number.isFinite(layer.opacity)||layer.opacity<0||layer.opacity>1||layer.kind==='composition'&&(layer.compositionId===null||!layer.compositionId.trim()||layer.compositionId.length>256)||layer.kind!=='composition'&&layer.compositionId!==null)throw new TypeError('Invalid composition layer');map.set(layer.id,layer);}
 for(const layer of layers){const ids=new Set<string>(),comps=new Set([compositionId]);let current:CompositionLayer|undefined=layer,depth=0;while(current){if(ids.has(current.id)||depth>64)throw new RangeError('Composition hierarchy is cyclic or deeper than 64');ids.add(current.id);if(current.kind==='composition'){if(comps.has(current.compositionId!))throw new TypeError('Nested composition reference creates a cycle');comps.add(current.compositionId!);}if(current.parentId===null)break;const parent=map.get(current.parentId);if(!parent||parent.kind!=='composition')throw new TypeError('Layer parent must be an existing composition layer');current=parent;depth++;}}
}
export function compositionAncestors(layers:readonly CompositionLayer[],id:string):readonly string[] {const map=new Map(layers.map(layer=>[layer.id,layer])),out:string[]=[],seen=new Set<string>();let current=map.get(id);while(current?.parentId){if(seen.has(current.parentId))throw new TypeError('Cyclic composition ancestors');seen.add(current.parentId);out.unshift(current.parentId);current=map.get(current.parentId);}return out;}
/** Stable sibling order follows the supplied document order, independent of expansion. */
export function flattenCompositionLayers(layers:readonly CompositionLayer[],expandedIds:readonly string[]):readonly CompositionTreeRow[] {const children=new Map<string|null,CompositionLayer[]>();for(const layer of layers){const rows=children.get(layer.parentId)??[];rows.push(layer);children.set(layer.parentId,rows);}const expanded=new Set(expandedIds),result:CompositionTreeRow[]=[],stack=(children.get(null)??[]).map(layer=>({layer,depth:0})).reverse();while(stack.length){const row=stack.pop()!,nested=children.get(row.layer.id)??[];result.push({...row,hasChildren:nested.length>0});if(expanded.has(row.layer.id))for(let i=nested.length-1;i>=0;i--)stack.push({layer:nested[i]!,depth:row.depth+1});}return result;}
